# -*- coding: utf-8 -*-
# توسعة: تربية إسلامية ومهارات حياتية للصفين 5 و6
from libspecs7 import *

def isl7():
    rules = ['ندخل المسجد بهدوء ونحترم المصلّين', 'ندخل بالرِّجل اليمنى ونذكر الله', 'نخلع الحذاء ونضعه في مكانه', 'نحافظ على نظافة المسجد ولا نرمي فيه شيئًا', 'نخفض صوت الجوال أو نغلقه', 'نصلّي ركعتين تحية للمسجد إن أمكن']
    body = '<p class="ins">هذه آداب يجب أن نلتزم بها في المسجد:</p>' + ''.join(f'<div class="bx" style="display:flex;gap:4mm;align-items:center"><span class="no" style="width:9mm;height:9mm">{i+1}</span><span style="font-size:14.5pt;font-weight:700">{r}</span></div>' for i, r in enumerate(rules))
    P = [('آداب المسجد', 'المسجد بيت من بيوت الله، ولدخوله آداب نتعلّمها.', body, 'ws')]
    t = [('نركض ونرفع أصواتنا داخل المسجد.', 'خطأ'), ('نحافظ على نظافة المسجد.', 'صح'), ('نترك الحذاء في أي مكان.', 'خطأ'), ('نحترم المصلّين ولا نزعجهم.', 'صح'), ('نترك الجوال يرنّ أثناء الصلاة.', 'خطأ'), ('نصلّي تحية المسجد عند الدخول إن أمكن.', 'صح')]
    P.append(('أحكم على التصرّف', 'اقرأ العبارة واختر صح أو خطأ.', tf(t), 'ws'))
    qs = [('دخل أحمد المسجد ووجد الناس يصلّون، فماذا يفعل؟', ['يتكلّم بصوت مرتفع', 'يدخل بهدوء ويحترم المصلّين', 'يركض بين الصفوف'], 'يدخل بهدوء ويحترم المصلّين'),
          ('وجدت ورقة مرميّة على أرض المسجد، فماذا تفعل؟', ['أتركها', 'أضعها في سلة المهملات', 'أرميها خارج الباب'], 'أضعها في سلة المهملات'),
          ('رنّ جوالك وأنت في المسجد، فماذا تفعل؟', ['أخفض الصوت أو أغلقه', 'أجيب بصوت عالٍ', 'أتركه يرنّ'], 'أخفض الصوت أو أغلقه')]
    body = mcq(qs) + f'<p class="ins" style="margin-top:4mm">اكتب أدبًا آخر من آداب المسجد:</p><div class="q" style="min-height:24mm"></div>'
    P.append(('ما التصرّف الصحيح؟', 'ضع دائرة حول الإجابة الصحيحة.', body, 'ws'))
    key = K('صح وخطأ', [a for _, a in t]) + K('التصرّف الصحيح', [a for *_, a in qs]) + '<p>الكتابة الحرّة: أي أدب صحيح من آداب المسجد.</p>'
    return fin(S5('g5-mosque-manners', 'آداب المسجد', 'أتعلّم كيف أتصرّف في بيت الله', ['الصف الخامس', 'التربية الإسلامية', 'الآداب', 'مع الحلول'], '#0d9488', '#dcf7f2', 'اطبع الصفحات وأجب عنها، ثم راجع الإجابات في الصفحة الأخيرة.'), P, key)

def isl8():
    body = '<p class="ins">صِل كل كلمة بمعناها:</p>' + line_match(['الصدق', 'الأمانة', 'الكذب'], shuf(['حفظ ما ائتُمنّا عليه وأداؤه لأهله', 'قول ما يوافق الحقيقة', 'قول ما يخالف الحقيقة'], 6))
    P = [('معنى الصدق والأمانة', 'الصدق والأمانة من أجمل الأخلاق. تعرّف على معناهما.', body, 'ws')]
    qs = [('وجدتَ محفظة في الشارع، فما التصرّف الأمانة؟', ['أحتفظ بها', 'أسلّمها لشرطي أو لصاحبها', 'أرميها'], 'أسلّمها لشرطي أو لصاحبها'),
          ('كسرتَ كوبًا في البيت، فما التصرّف الصادق؟', ['أخبر والديّ بما حدث', 'أتّهم أخي', 'أخفي الكوب'], 'أخبر والديّ بما حدث'),
          ('استعرتَ كتابًا من صديقك، فماذا يجب عليك؟', ['أنساه عندي', 'أعيده في الوقت المتّفق عليه', 'أعطيه لشخص آخر'], 'أعيده في الوقت المتّفق عليه')]
    P.append(('ماذا أفعل؟', 'ضع دائرة حول التصرّف الصحيح.', mcq(qs), 'ws'))
    t = [('الصادق يقول الحقيقة حتى لو كانت تصعب عليه.', 'صح'), ('الأمين يحفظ الأشياء التي تُسلَّم إليه.', 'صح'), ('الكذب يجعل الناس تثق بنا أكثر.', 'خطأ'), ('نحافظ على أسرار أصدقائنا الخاصة.', 'صح')]
    body = tf(t) + '<p class="ins" style="margin-top:5mm">اكتب موقفًا كنتَ فيه صادقًا أو أمينًا:</p><div class="q" style="min-height:40mm"></div>'
    P.append(('أحكم وأكتب', 'اختر صح أو خطأ ثم اكتب موقفًا من حياتك.', body, 'ws'))
    key = '<p><b>التوصيل:</b> الصدق ← قول ما يوافق الحقيقة، الأمانة ← حفظ ما ائتُمنّا عليه وأداؤه لأهله، الكذب ← قول ما يخالف الحقيقة.</p>' + K('ماذا أفعل', [a for *_, a in qs]) + K('صح وخطأ', [a for _, a in t]) + '<p>الكتابة حرّة.</p>'
    return fin(S5('g6-honesty-and-trust', 'الصدق والأمانة', 'أفهم معنى الصدق والأمانة وأطبّقهما', ['الصف السادس', 'التربية الإسلامية', 'الأخلاق', 'مع الحلول'], '#4f46e5', '#e6e7ff', 'اطبع الصفحات وأجب عنها، ثم راجع الإجابات في الصفحة الأخيرة.'), P, key)

def ls7():
    C, T = '#16a34a', '#e0f7e8'
    F = [('1f34e', 'تفاحة', 'كل يوم'), ('1f955', 'جزرة', 'كل يوم'), ('1f95b', 'حليب', 'كل يوم'), ('1f35e', 'خبز', 'كل يوم'), ('1f36c', 'حلوى', 'نقلّل'), ('1f36b', 'شوكولاتة', 'نقلّل'), ('1f36a', 'بسكويت محلّى', 'نقلّل'), ('1f355', 'بيتزا', 'نقلّل')]
    P = [('أختار غذائي', 'بعض الأطعمة مفيدة نأكلها كل يوم، وبعضها نقلّل منه. ضع دائرة حول الإجابة.', tiles([(a, f'<b>{n}</b><br>{chips(["كل يوم", "نقلّل"])}') for a, n, _ in F], 4, 18), 'ws')]
    body = '<p class="ins">خطّط لوجبة إفطار صحية. اختر من الصندوق واكتب:</p>' + f'<div class="bx" style="text-align:center">{chips(["بيضة", "خبز", "حليب", "تفاحة", "حلوى", "جبن"])}</div><div class="bx" style="line-height:2.6">طعام رئيسي: {ans_line(40)}<br>مشروب: {ans_line(40)}<br>فاكهة: {ans_line(40)}</div><p class="ins" style="margin-top:4mm">ارسم طبق غدائك الصحي:</p><div class="q" style="min-height:60mm"></div>'
    P.append(('وجبتي الصحية', 'اختر أطعمة مفيدة.', body, 'ws'))
    t = [('الفواكه والخضار تفيد الجسم.', 'صح'), ('نشرب الماء بانتظام خلال اليوم.', 'صح'), ('نتناول الحلوى بدل الوجبات.', 'خطأ'), ('نغسل أيدينا قبل الأكل.', 'صح'), ('نأكل بسرعة دون مضغ.', 'خطأ')]
    P.append(('صح أم خطأ؟', 'اقرأ العبارة واختر.', tf(t), 'ws'))
    key = K('الصفحة 2', [f'{n}: {a}' for _, n, a in F]) + '<p>الصفحة 3: يقبل أي اختيار منطقي، وتُستبعد الحلوى من الوجبة الصحية.</p>' + K('الصفحة 4', [a for _, a in t])
    return fin(S5('g5-healthy-eating', 'غذائي الصحي', 'أميّز الأطعمة المفيدة وأخطّط لوجبة صحية', ['الصف الخامس', 'المهارات الحياتية', 'الصحة', 'مع الحلول'], C, T, 'اطبع الصفحات وأجب عنها، ثم راجع الإجابات في الصفحة الأخيرة.'), P, key)

def ls8():
    C, T = '#2563eb', '#dfe9ff'
    rules = ['لا أشارك كلمة المرور مع أحد غير والديّ', 'لا أعطي اسمي الكامل أو عنواني أو مدرستي لغرباء', 'أفكّر قبل نشر أي صورة أو كلام', 'لا أفتح روابط أو ملفات من أشخاص لا أعرفهم', 'أخبر شخصًا كبيرًا موثوقًا إذا شعرت بالقلق من رسالة']
    body = '<p class="ins">قواعد تحميني على الإنترنت:</p>' + ''.join(f'<div class="bx" style="display:flex;gap:4mm;align-items:center"><span class="no" style="width:9mm;height:9mm">{i+1}</span><span style="font-size:14.5pt;font-weight:700">{r}</span></div>' for i, r in enumerate(rules))
    P = [('أحمي نفسي على الإنترنت', 'الإنترنت مفيد، ويحتاج إلى حذر.', body, 'ws')]
    qs = [('طلب منك شخص لا تعرفه كلمة مرور حسابك، فماذا تفعل؟', ['أعطيه كلمة المرور', 'أرفض وأخبر شخصًا كبيرًا', 'أرسلها له في رسالة'], 'أرفض وأخبر شخصًا كبيرًا'),
          ('وصلتك رسالة فيها رابط من شخص مجهول، فماذا تفعل؟', ['أفتح الرابط بسرعة', 'لا أفتحه وأخبر والديّ', 'أرسله لأصدقائي'], 'لا أفتحه وأخبر والديّ'),
          ('أيّ هذه المعلومات يمكن أن أشاركها مع غرباء؟', ['عنوان بيتي', 'اسم لعبتي المفضّلة', 'كلمة المرور'], 'اسم لعبتي المفضّلة')]
    P.append(('ماذا أفعل؟', 'ضع دائرة حول التصرّف الآمن.', mcq(qs), 'ws'))
    t = [('كلمة المرور سرّ لا أشاركه.', 'صح'), ('أقبل طلبات الصداقة من أي شخص.', 'خطأ'), ('أفكّر قبل أن أنشر صورة.', 'صح'), ('أخبر شخصًا كبيرًا إذا أزعجني أحد.', 'صح')]
    P.append(('صح أم خطأ؟', 'اقرأ العبارة واختر.', tf(t) + '<p class="ins" style="margin-top:5mm">اكتب ثلاث قواعد ستلتزم بها على الإنترنت:</p><div class="q" style="min-height:45mm"></div>', 'ws'))
    key = K('ماذا أفعل', [a for *_, a in qs]) + K('صح وخطأ', [a for _, a in t]) + '<p>الكتابة حرّة: أي قواعد آمنة صحيحة.</p>'
    return fin(S5('g6-online-safety', 'سلامتي على الإنترنت', 'أتعلّم حماية معلوماتي والتصرّف الآمن', ['الصف السادس', 'المهارات الحياتية', 'السلامة الرقمية', 'مع الحلول'], C, T, 'اطبع الصفحات وأجب عنها، ثم راجع الإجابات في الصفحة الأخيرة.'), P, key)

ALL.update(isl7=isl7, isl8=isl8, ls7=ls7, ls8=ls8)
